{
  "category": "ETL",
  "config": {
    "pipeline": {
      "edges": [
        {
          "from": "src_1",
          "to": "tr_1"
        },
        {
          "from": "tr_1",
          "to": "snk_1"
        }
      ],
      "name": "Custom ETL",
      "nodes": [
        {
          "config": {
            "path": "samples/data/orders.csv"
          },
          "id": "src_1",
          "plugin": "csv",
          "type": "source"
        },
        {
          "config": {
            "expression": "amount > 50"
          },
          "id": "tr_1",
          "plugin": "filter",
          "type": "transform"
        },
        {
          "config": {
            "path": "outputs/clean.csv"
          },
          "id": "snk_1",
          "plugin": "csv",
          "type": "sink"
        }
      ]
    }
  },
  "description": "Custom CSV filter and extract template",
  "name": "My Custom ETL"
}

{
  "run_failed": {
    "email": true,
    "in_app": true,
    "webhook": true
  },
  "run_succeeded": {
    "email": false,
    "in_app": true,
    "webhook": false
  },
  "schedule_missed": {
    "email": false,
    "in_app": true,
    "webhook": true
  }
}
